export interface BaseNode {
  type: string;
}

export interface BaseCallExpression extends BaseNode {
  callee: Expression;
}

export interface NewExpression extends BaseCallExpression {
  type: "NewExpression";
}

export interface ObjectExpression extends BaseNode {
  properties: Array<Property>;
}

export interface Property extends BaseNode {
  value: Expression;
}

export type Expression = ObjectExpression | NewExpression;

export type CallExpression = SimpleCallExpression | NewExpression;

export interface SimpleCallExpression extends BaseCallExpression {
  type: "CallExpression";
  optional: boolean;
}

export type Pattern = Identifier | ObjectPattern | RestElement;

export interface Identifier extends BaseNode {
  type: "Identifier";
  name: string;
}

export interface ObjectPattern extends BaseNode {
  type: "ObjectPattern";
  properties: Array<AssignmentProperty | RestElement>;
}

export interface PropertyBase extends BaseNode {
  type: "Property";
}

export interface AssignmentProperty extends PropertyBase {
  value: Pattern;
}

export interface RestElement extends BaseNode {
  type: "RestElement";
  argument: Pattern;
  value: Pattern;
}
